begin;
create or replace function public.app_admin_listar_ferias_gestao_completa(p_token text) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare v record; base jsonb; rec jsonb; begin select * into v from public.app_tenant_usuario(p_token) limit 1; if v.usuario_id is null or v.perfil not in ('admin','administrador') then return jsonb_build_object('sucesso',false,'erro','Acesso restrito ao administrador'); end if; base:=public.app_admin_listar_ferias_gestao(p_token); rec:=coalesce(base->'reconciliacao','{}'::jsonb) || jsonb_build_object('pagamentos_total',(select count(*)::int from public.rh_ferias_documentos d where d.empresa_id=v.empresa_id and d.tipo='comprovante_pagamento' and d.storage_path is not null),'pagamentos_sem_aviso',(select count(*)::int from public.rh_ferias_documentos d where d.empresa_id=v.empresa_id and d.tipo='comprovante_pagamento' and d.storage_path is not null and (d.ferias_id is null or not exists(select 1 from public.rh_ferias_documentos a where a.ferias_id=d.ferias_id and a.empresa_id=v.empresa_id and a.tipo='aviso' and a.storage_path is not null))),'pagamentos_sem_recibo',(select count(*)::int from public.rh_ferias_documentos d where d.empresa_id=v.empresa_id and d.tipo='comprovante_pagamento' and d.storage_path is not null and (d.ferias_id is null or not exists(select 1 from public.rh_ferias_documentos r where r.ferias_id=d.ferias_id and r.empresa_id=v.empresa_id and r.tipo='recibo' and r.storage_path is not null))),'periodos_sem_pagamento',(select count(*)::int from public.rh_ferias r where r.empresa_id=v.empresa_id and r.status<>'cancelada' and exists(select 1 from public.rh_ferias_documentos d where d.ferias_id=r.id and d.empresa_id=v.empresa_id and d.tipo in ('aviso','recibo') and d.storage_path is not null) and not exists(select 1 from public.rh_ferias_documentos p where p.ferias_id=r.id and p.empresa_id=v.empresa_id and p.tipo='comprovante_pagamento' and p.storage_path is not null)),'aquisicoes_incompletas',(select count(*)::int from public.rh_ferias_programacao_historica h where h.empresa_id=v.empresa_id and (h.funcionario_id is null or h.dias_direito is null or h.aquisitivo_inicio is null or h.aquisitivo_fim is null))); return base || jsonb_build_object('reconciliacao',rec); end; $$;
grant execute on function public.app_admin_listar_ferias_gestao_completa(text) to anon,authenticated;
commit;
